import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.DT_qyuxR.js";const v=JSON.parse('{"title":"Les Camps","description":"","frontmatter":{},"headers":[],"relativePath":"gitbook/regles/03-camps.md","filePath":"gitbook/regles/03-camps.md"}'),i={name:"gitbook/regles/03-camps.md"};function l(r,e,o,u,d,c){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="les-camps" tabindex="-1">Les Camps <a class="header-anchor" href="#les-camps" aria-label="Permalink to &quot;Les Camps&quot;">​</a></h1><h2 id="vue-d-ensemble" tabindex="-1">Vue d&#39;ensemble <a class="header-anchor" href="#vue-d-ensemble" aria-label="Permalink to &quot;Vue d&#39;ensemble&quot;">​</a></h2><p>La partie oppose deux camps. Le camp de chaque joueur est tiré au sort au début de la partie et reste secret jusqu&#39;à la fin.</p><table tabindex="0"><thead><tr><th>Camp</th><th>Objectif</th><th>Connaissance</th></tr></thead><tbody><tr><td><strong>Vivant</strong></td><td>Éliminer tous les Revenants</td><td>Connaît son propre camp uniquement</td></tr><tr><td><strong>Revenant</strong> (le Cercle)</td><td>Éliminer tous les Vivants</td><td>Connaît tous les autres Revenants</td></tr></tbody></table><h2 id="les-vivants" tabindex="-1">Les Vivants <a class="header-anchor" href="#les-vivants" aria-label="Permalink to &quot;Les Vivants&quot;">​</a></h2><p>Les Vivants sont les Invités ordinaires du bal. Ils ne savent pas qui sont les Revenants. Leur seule certitude : ils ne sont pas seuls.</p><h3 id="ce-que-les-vivants-savent" tabindex="-1">Ce que les Vivants savent <a class="header-anchor" href="#ce-que-les-vivants-savent" aria-label="Permalink to &quot;Ce que les Vivants savent&quot;">​</a></h3><ul><li>Ils sont Vivants (leur camp).</li><li>Le <strong>nombre total de Revenants</strong> (affiché au début de la partie).</li><li>Ce qu&#39;ils observent : les masques qui se brisent, les accusations, les alliances.</li></ul><h3 id="ce-que-les-vivants-ne-savent-pas" tabindex="-1">Ce que les Vivants ne savent pas <a class="header-anchor" href="#ce-que-les-vivants-ne-savent-pas" aria-label="Permalink to &quot;Ce que les Vivants ne savent pas&quot;">​</a></h3><ul><li>Qui sont les Revenants.</li><li>Les PV des autres joueurs.</li><li>Les camps des autres joueurs (sauf par déduction ou par le pouvoir de certains masques).</li></ul><h3 id="strategie-des-vivants" tabindex="-1">Stratégie des Vivants <a class="header-anchor" href="#strategie-des-vivants" aria-label="Permalink to &quot;Stratégie des Vivants&quot;">​</a></h3><ul><li>Réseauter, accuser sans preuve, défendre les alliés.</li><li>Utiliser les masques à capacités d&#39;information (Medium, Oracle, Sans-Visage).</li><li>Protéger les joueurs utiles.</li><li>Éliminer les suspects par les Duels.</li></ul><h2 id="les-revenants-le-cercle" tabindex="-1">Les Revenants (le Cercle) <a class="header-anchor" href="#les-revenants-le-cercle" aria-label="Permalink to &quot;Les Revenants (le Cercle)&quot;">​</a></h2><p>Les Revenants sont les Invités possédés par l&#39;esprit du bal. Ils forment un groupe secret qui tire profit de la nuit.</p><h3 id="ce-que-les-revenants-savent" tabindex="-1">Ce que les Revenants savent <a class="header-anchor" href="#ce-que-les-revenants-savent" aria-label="Permalink to &quot;Ce que les Revenants savent&quot;">​</a></h3><ul><li>Ils sont Revenants (leur camp).</li><li><strong>Qui sont tous les autres Revenants</strong> (ils se reconnaissent entre eux).</li><li>Le nombre total de Vivants.</li></ul><h3 id="ce-que-les-revenants-ne-savent-pas" tabindex="-1">Ce que les Revenants ne savent pas <a class="header-anchor" href="#ce-que-les-revenants-ne-savent-pas" aria-label="Permalink to &quot;Ce que les Revenants ne savent pas&quot;">​</a></h3><ul><li>Les PV des Vivants.</li><li>Les identités exactes des Vivants (sauf par déduction).</li><li>Qui parmi les Vivants est le plus dangereux.</li></ul><h3 id="strategie-des-revenants" tabindex="-1">Stratégie des Revenants <a class="header-anchor" href="#strategie-des-revenants" aria-label="Permalink to &quot;Stratégie des Revenants&quot;">​</a></h3><ul><li>Se fondre dans la masse : ne pas se faire remarquer.</li><li>Éliminer les Vivants en douce pendant la Nuit.</li><li>Protéger les alliés Revenants (en les défendant lors des Duels).</li><li>Créer la confusion : accuser des Vivants entre eux.</li><li>Éviter les Duels risqués.</li></ul><h2 id="distribution-des-camps" tabindex="-1">Distribution des camps <a class="header-anchor" href="#distribution-des-camps" aria-label="Permalink to &quot;Distribution des camps&quot;">​</a></h2><h3 id="nombre-de-revenants" tabindex="-1">Nombre de Revenants <a class="header-anchor" href="#nombre-de-revenants" aria-label="Permalink to &quot;Nombre de Revenants&quot;">​</a></h3><p>Le nombre de Revenants est calculé automatiquement :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Revenants = max(1, round(N joueurs / 3))</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Joueurs</th><th>Revenants</th></tr></thead><tbody><tr><td>6</td><td>2</td></tr><tr><td>7</td><td>2</td></tr><tr><td>8</td><td>3</td></tr><tr><td>9</td><td>3</td></tr><tr><td>10</td><td>3-4</td></tr><tr><td>11</td><td>4</td></tr><tr><td>12</td><td>4</td></tr></tbody></table><h3 id="processus-de-distribution" tabindex="-1">Processus de distribution <a class="header-anchor" href="#processus-de-distribution" aria-label="Permalink to &quot;Processus de distribution&quot;">​</a></h3><ol><li>Le bot tire aléatoirement les camps.</li><li>Chaque joueur reçoit secrètement son camp (en MP).</li><li>Les Revenants voient la liste des autres Revenants.</li><li>L&#39;Hôte du Carnaval valide la composition.</li><li>Une fois validée, la composition est <strong>verrouillée</strong> et ne peut plus être modifiée.</li></ol><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><p>L&#39;Hôte du Carnaval peut :</p><ul><li><strong>Valider</strong> la composition telle quelle.</li><li><strong>Relancer</strong> le tirage si la composition semble déséquilibrée (optionnel).</li></ul><blockquote><p><strong>Important</strong> : la composition réelle n&#39;est révélée qu&#39;à la fin de la partie. Personne ne peut prouver qui est Revenant sauf par déduction.</p></blockquote><h2 id="revelation" tabindex="-1">Révélation <a class="header-anchor" href="#revelation" aria-label="Permalink to &quot;Révélation&quot;">​</a></h2><h3 id="au-bris-de-masque" tabindex="-1">Au bris de masque <a class="header-anchor" href="#au-bris-de-masque" aria-label="Permalink to &quot;Au bris de masque&quot;">​</a></h3><p>Quand un masque se brise, <strong>seule l&#39;identité du joueur est révélée</strong> (son nom de masque). Son <strong>camp reste secret</strong>.</p><blockquote><p><em>Exemple : si &quot;Marie&quot; porte le masque de l&#39;Épine et que son masque se brise, le bot annonce : &quot;Masque brisé — Marie est K.O. Son identité était Masque de l&#39;Épine.&quot; Le camp de Marie n&#39;est pas révélé.</em></p></blockquote><h3 id="a-la-fin-de-la-partie" tabindex="-1">À la fin de la partie <a class="header-anchor" href="#a-la-fin-de-la-partie" aria-label="Permalink to &quot;À la fin de la partie&quot;">​</a></h3><p>Quand un camp gagne, le bot révèle <strong>toute la composition</strong> :</p><ul><li>Chaque joueur et son masque.</li><li>Chaque joueur et son camp.</li><li>Le nombre de Revenants et de Vivants.</li></ul>',38)])])}const h=a(i,[["render",l]]);export{v as __pageData,h as default};
